changeSet.sql:
CREATE TABLE nexus.data_moves ( label TEXT NOT NULL, template TEXT NOT NULL, driving_schema TEXT NOT NULL, driving_table TEXT NOT NULL, chunk_size INTEGER NOT NULL, sleep_ms INTEGER NOT NULL, statement_timeout_ms INTEGER NOT NULL, verification TEXT NOT NULL, on_complete TEXT, changeset_id TEXT NOT NULL, supersedes TEXT, registered_at TIMESTAMPTZ NOT NULL DEFAULT now(), failed_at TIMESTAMPTZ, failure TEXT, completed_at TIMESTAMPTZ, transient_retries INTEGER NOT NULL DEFAULT 0, last_transient_at TIMESTAMPTZ, last_transient TEXT, paused_at TIMESTAMPTZ, paused_by TEXT, CONSTRAINT data_moves_pk PRIMARY KEY (label), CONSTRAINT data_moves_label_check CHECK (label !~ '/'), CONSTRAINT data_moves_label_nonempty_check CHECK (label <> ''), CONSTRAINT data_moves_chunk_size_check CHECK (chunk_size BETWEEN 1 AND 1000000), CONSTRAINT data_moves_sleep_ms_check CHECK (sleep_ms BETWEEN 0 AND 60000), CONSTRAINT data_moves_statement_timeout_ms_check CHECK (statement_timeout_ms > 0), CONSTRAINT data_moves_supersedes_unique UNIQUE (supersedes), CONSTRAINT data_moves_supersedes_fk FOREIGN KEY (supersedes) REFERENCES nexus.data_moves (label), CONSTRAINT data_moves_supersedes_self_check CHECK (supersedes <> label), CONSTRAINT data_moves_terminal_exclusive_check CHECK (failed_at IS NULL OR completed_at IS NULL), CONSTRAINT data_moves_failure_pair_check CHECK ((failed_at IS NULL) = (failure IS NULL)), CONSTRAINT data_moves_transient_retries_check CHECK (transient_retries >= 0), CONSTRAINT data_moves_transient_pair_check CHECK ((last_transient_at IS NULL) = (last_transient IS NULL)), CONSTRAINT data_moves_transient_retries_stamp_check CHECK ((transient_retries = 0) = (last_transient_at IS NULL)), CONSTRAINT data_moves_paused_by_check CHECK (paused_by IS NULL OR paused_at IS NOT NULL) );
-- The worker's scan: open moves, oldest first. A paused move is still open; the worker filters it in its query. CREATE INDEX data_moves_open_registered_at ON nexus.data_moves (registered_at) WHERE completed_at IS NULL AND failed_at IS NULL;
-- On an upgrade, ALTER DEFAULT PRIVILEGES (installed by an earlier boot's grants-nexus-svc-1) gave nexus_svc DML -- on this table the moment it was created; on a fresh walk that default ACL does not exist yet. -- Skipped when the migrating role is nexus_svc itself (an owner revoking its own rights would only lock out -- the one connection that works the registry). DO $$ BEGIN IF current_user <> 'nexus_svc' AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'nexus_svc') THEN REVOKE ALL ON TABLE nexus.data_moves FROM nexus_svc; END IF; END $$;
